SET NOCOUNT ON; SET XACT_ABORT OFF; SET QUOTED_IDENTIFIER ON;
IF (SELECT COUNT(*) FROM commerce.Provider WHERE Category='Grocery')<>7 THROW 52200,'Expected seven grocery platforms',1;
IF (SELECT COUNT(*) FROM commerce.Provider WHERE Category='Pharmacy')<>7 THROW 52200,'Expected seven pharmacies',1;
IF EXISTS(SELECT 1 FROM cfg.Menu WHERE Code IN ('wealth','goals') AND IsVisible=1) THROW 52200,'Removed menus still visible',1;
IF (SELECT COUNT(*) FROM cfg.LanguagePresentation WHERE IsInterfaceEnabled=1)<>3 THROW 52200,'Expected three UI languages',1;
IF NOT EXISTS(SELECT 1 FROM cfg.LanguagePresentation p JOIN cfg.Language l ON l.Id=p.LanguageId WHERE l.Code='ar' AND p.Direction='rtl') THROW 52200,'Arabic RTL missing',1;
IF (SELECT COUNT(*) FROM cfg.fnInterfaceText('ar'))<>472 THROW 52200,'Translation catalogue incomplete',1;
IF EXISTS(SELECT 1 FROM cfg.fnInterfaceText('unknown') WHERE DisplayText<>SourceText) THROW 52200,'English fallback mismatch',1;
IF EXISTS(SELECT 1 FROM commerce.vComparisonSummary WHERE IsEligibleForLiveRanking=1) THROW 52200,'Demo quote claimed live rank',1;
IF (SELECT COUNT(*) FROM sys.security_predicates WHERE target_object_id=OBJECT_ID('family.InterfacePreference'))<>3 THROW 52200,'Missing security predicates: family.InterfacePreference',1;
IF (SELECT COUNT(*) FROM sys.security_predicates WHERE target_object_id=OBJECT_ID('finance.PlanScenario'))<>3 THROW 52200,'Missing security predicates: finance.PlanScenario',1;
IF (SELECT COUNT(*) FROM sys.security_predicates WHERE target_object_id=OBJECT_ID('finance.PlanPerson'))<>3 THROW 52200,'Missing security predicates: finance.PlanPerson',1;
IF (SELECT COUNT(*) FROM sys.security_predicates WHERE target_object_id=OBJECT_ID('finance.PlanAsset'))<>3 THROW 52200,'Missing security predicates: finance.PlanAsset',1;
IF (SELECT COUNT(*) FROM sys.security_predicates WHERE target_object_id=OBJECT_ID('finance.PlanDebt'))<>3 THROW 52200,'Missing security predicates: finance.PlanDebt',1;
IF (SELECT COUNT(*) FROM sys.security_predicates WHERE target_object_id=OBJECT_ID('finance.PlanFlow'))<>3 THROW 52200,'Missing security predicates: finance.PlanFlow',1;
IF (SELECT COUNT(*) FROM sys.security_predicates WHERE target_object_id=OBJECT_ID('finance.PlanPolicy'))<>3 THROW 52200,'Missing security predicates: finance.PlanPolicy',1;
IF (SELECT COUNT(*) FROM sys.security_predicates WHERE target_object_id=OBJECT_ID('finance.PlanGoal'))<>3 THROW 52200,'Missing security predicates: finance.PlanGoal',1;
IF (SELECT COUNT(*) FROM sys.security_predicates WHERE target_object_id=OBJECT_ID('commerce.QuoteVerification'))<>3 THROW 52200,'Missing security predicates: commerce.QuoteVerification',1;
PRINT 'PASS: 14 platforms, consolidated menus, 3 UI languages, 472 translations and fallback.';
IF NOT EXISTS(SELECT 1 FROM dbo.SchemaMigration WHERE Version='010') BEGIN PRINT 'Reference checks complete; demo checks skipped.'; RETURN; END;
EXEC sys.sp_set_session_context @key=N'HouseholdId',@value=NULL;
IF EXISTS(SELECT 1 FROM finance.PlanScenario) OR EXISTS(SELECT 1 FROM family.InterfacePreference) THROW 52200,'New tables leak without context',1;
EXEC sys.sp_set_session_context @key=N'HouseholdId',@value=2;
IF EXISTS(SELECT 1 FROM finance.PlanGoal) OR EXISTS(SELECT 1 FROM finance.PlanScenario) THROW 52200,'Plan leaked to another household',1;
EXEC sys.sp_set_session_context @key=N'HouseholdId',@value=1;
IF NOT EXISTS(SELECT 1 FROM finance.vPlanOverview WHERE Assets=7500000 AND NetWorth=5500000 AND UnallocatedCash=57500 AND CapacityBeforeInvestments=77500 AND EmergencyTarget=333000) THROW 52200,'Plan fixture cashflow incorrect',1;
IF (SELECT COUNT(*) FROM commerce.DemoOffer WHERE PackPrice IS NULL)<>25 THROW 52200,'Missing prices must remain NULL',1;
DECLARE @Plan bigint=(SELECT MIN(Id) FROM finance.PlanScenario),@err int=0;
BEGIN TRY BEGIN TRANSACTION;
INSERT finance.PlanGoal(HouseholdId,ScenarioId,Name,CurrentCost,TargetBasis,TargetAge) VALUES(1,@Plan,N'Invalid age goal',100,'Age',18);
ROLLBACK; END TRY BEGIN CATCH SET @err=ERROR_NUMBER();IF @@TRANCOUNT>0 ROLLBACK;END CATCH;
IF @err<>547 THROW 52200,'Age goal without member was accepted',1;
SET @err=0;
BEGIN TRY BEGIN TRANSACTION;
INSERT finance.PlanScenario(HouseholdId,Name,AsOfDate) VALUES(2,N'Cross tenant','20261025');
ROLLBACK; END TRY BEGIN CATCH SET @err=ERROR_NUMBER();IF @@TRANCOUNT>0 ROLLBACK;END CATCH;
IF @err<>33504 THROW 52200,'Cross household plan write was accepted',1;
EXEC sys.sp_set_session_context @key=N'HouseholdId',@value=NULL;
PRINT 'PASS: plan amounts, unknown quotes, tenant isolation, blocked tenant writes and goal constraints.';

BEGIN TRANSACTION;
CREATE USER AarohiLatestPermissionTest WITHOUT LOGIN;
ALTER ROLE aarohi_app ADD MEMBER AarohiLatestPermissionTest;
EXECUTE AS USER='AarohiLatestPermissionTest';
DECLARE @Denied bit=0;
BEGIN TRY EXEC(N'UPDATE commerce.DemoOffer SET PackPrice=0;'); END TRY BEGIN CATCH IF ERROR_NUMBER()=229 SET @Denied=1; ELSE THROW; END CATCH;
IF @Denied=0 BEGIN REVERT; ROLLBACK; THROW 52200,'Application can modify global demo offers',1; END;
IF EXISTS(SELECT 1 FROM finance.PlanScenario) BEGIN REVERT; ROLLBACK; THROW 52200,'Application leaked plans without tenant context',1; END;
EXEC sys.sp_set_session_context @key=N'HouseholdId',@value=1;
IF NOT EXISTS(SELECT 1 FROM finance.vPlanOverview) BEGIN REVERT; ROLLBACK; THROW 52200,'Application cannot read authorized plan view',1; END;
IF EXISTS(SELECT 1 FROM commerce.vComparisonSummary WHERE IsEligibleForLiveRanking=1) BEGIN REVERT; ROLLBACK; THROW 52200,'Demo quote claimed live rank',1; END;
REVERT; ROLLBACK;
EXEC sys.sp_set_session_context @key=N'HouseholdId',@value=NULL;
PRINT 'PASS: all new RLS predicates and application grants checked.';
